public void tick() {
   if (this.getHurtTime() > 0) {
      this.setHurtTime(this.getHurtTime() - 1);
   }

   if (this.getDamage() > 0.0F) {
      this.setDamage(this.getDamage() - 1.0F);
   }

   this.checkBelowWorld();
   this.computeSpeed();
   this.handlePortal();
   this.behavior.tick();
   this.updateFluidInteraction();
   if (this.isInLava()) {
